package fr.atelierdugoblin.mobile;
import android.app.*;
import android.content.*;
import android.net.Uri;
import android.webkit.JavascriptInterface;
import org.json.*;
import java.util.UUID;

/** A private local copy of PC reminders; no background network polling. */
public final class ReminderBridge {
    static final Object LOCK=new Object();
    final Activity activity;
    ReminderBridge(Activity a){activity=a;}
    static SharedPreferences prefs(Context c){return c.getSharedPreferences("goblin-native-reminders-v1",Context.MODE_PRIVATE);}
    static PendingIntent pending(Context c,String id,long end){Intent i=new Intent(c,ReminderReceiver.class).setAction("fr.atelierdugoblin.REMINDER").setData(Uri.parse("goblin-reminder://alarm/"+Uri.encode(id))).putExtra("id",id).putExtra("end",end);return PendingIntent.getBroadcast(c,0,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);}
    @JavascriptInterface public String status(){try{return new JSONObject().put("enabled",prefs(activity).getBoolean("enabled",false)).put("exact",KitchenTimerBridge.exact(activity)).put("notifications",((NotificationManager)activity.getSystemService(Context.NOTIFICATION_SERVICE)).areNotificationsEnabled()).put("last_sync",prefs(activity).getLong("last_sync",0)).put("error",prefs(activity).getString("error","")).put("pending",new JSONArray(prefs(activity).getString("actions","[]")).length()).toString();}catch(Exception e){return "{}";}}
    @JavascriptInterface public void enable(boolean enabled){synchronized(LOCK){prefs(activity).edit().putBoolean("enabled",enabled).commit();resume(activity);}}
    @JavascriptInterface public String backup(){try{SharedPreferences p=prefs(activity);return new JSONObject().put("enabled",p.getBoolean("enabled",false)).put("base",p.getString("base","")).put("identity",p.getString("identity","")).put("reminders",new JSONArray(p.getString("reminders","[]"))).put("actions",new JSONArray(p.getString("actions","[]"))).toString();}catch(Exception e){return "{}";}}
    @JavascriptInterface public boolean restore(String raw){synchronized(LOCK){try{if(raw.length()>2000000)return false;JSONObject b=new JSONObject(raw);JSONArray rows=b.getJSONArray("reminders"),actions=b.getJSONArray("actions");if(rows.length()>12000||actions.length()>500)return false;for(int n=0;n<rows.length();n++){JSONObject r=rows.getJSONObject(n);if(!r.getString("id").matches("-?[0-9]{1,18}")||r.getLong("end")<0||r.getString("title").length()>240||r.getString("due_key").length()>80)return false;}cancel(activity,new JSONArray(prefs(activity).getString("reminders","[]")));if(!prefs(activity).edit().putBoolean("enabled",b.optBoolean("enabled",false)).putString("base",b.optString("base","")).putString("identity",b.optString("identity","")).putString("reminders",rows.toString()).putString("actions",actions.toString()).commit())return false;resume(activity);return true;}catch(Exception e){return false;}}}
    @JavascriptInterface public String actions(){return prefs(activity).getString("actions","[]");}
    @JavascriptInterface public void acknowledge(String operation){synchronized(LOCK){try{JSONArray old=new JSONArray(actions()),next=new JSONArray();for(int n=0;n<old.length();n++){JSONObject a=old.getJSONObject(n);if(!a.getString("operation_id").equals(operation))next.put(a);}prefs(activity).edit().putString("actions",next.toString()).commit();}catch(Exception ignored){}}}
    @JavascriptInterface public boolean sync(String base,String identity,String raw){synchronized(LOCK){try{Uri uri=Uri.parse(base);if(!"https".equals(uri.getScheme())||uri.getHost()==null||!uri.getHost().endsWith(".ts.net")||identity.length()>100||raw.length()>2000000)return false;
        JSONArray rows=new JSONArray(raw),clean=new JSONArray();if(rows.length()>12000)return false;
        for(int n=0;n<rows.length();n++){JSONObject r=rows.getJSONObject(n);long rid=r.getLong("id"),end=r.getLong("trigger_at_ms");if(end<0)throw new IllegalArgumentException();String title=r.optString("title");if(title.isEmpty())title=r.optString("entity_title","Rappel");clean.put(new JSONObject().put("id",Long.toString(rid)).put("end",end).put("title",title.substring(0,Math.min(240,title.length()))).put("due_key",r.optString("snoozed_until").isEmpty()||r.isNull("snoozed_until")?r.getString("remind_at"):r.getString("snoozed_until")));}
        SharedPreferences p=prefs(activity);String oldBase=p.getString("base",""),oldIdentity=p.getString("identity","");if((!oldBase.isEmpty()&&!oldBase.equals(base))||(!oldIdentity.isEmpty()&&!oldIdentity.equals(identity))){if(new JSONArray(p.getString("actions","[]")).length()>0)return false;clear(activity);}
        JSONArray old=new JSONArray(p.getString("reminders","[]"));cancel(activity,old);if(!p.edit().putString("base",base).putString("identity",identity).putString("reminders",clean.toString()).putLong("last_sync",System.currentTimeMillis()).putString("error","").commit())return false;resume(activity);return true;
    }catch(Exception e){prefs(activity).edit().putString("error","Copie des rappels refusée ; la précédente est conservée.").commit();return false;}}}
    @JavascriptInterface public boolean test(){synchronized(LOCK){try{if(!prefs(activity).getBoolean("enabled",false))return false;JSONArray rows=new JSONArray(prefs(activity).getString("reminders","[]")),next=new JSONArray();for(int n=0;n<rows.length();n++)if(!rows.getJSONObject(n).getString("id").equals("0"))next.put(rows.getJSONObject(n));next.put(new JSONObject().put("id","0").put("end",System.currentTimeMillis()+30000).put("title","Rappel de test Android").put("due_key","test"));prefs(activity).edit().putString("reminders",next.toString()).commit();resume(activity);return true;}catch(Exception e){return false;}}}
    @JavascriptInterface public void disconnect(){synchronized(LOCK){clear(activity);}}
    static void clear(Context c){try{cancel(c,new JSONArray(prefs(c).getString("reminders","[]")));prefs(c).edit().remove("reminders").remove("base").remove("identity").remove("last_sync").commit();}catch(Exception ignored){}}
    static void cancel(Context c,JSONArray rows)throws Exception{AlarmManager alarms=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);for(int n=0;n<rows.length();n++){JSONObject r=rows.getJSONObject(n);alarms.cancel(pending(c,r.getString("id"),r.getLong("end")));}}
    static void resume(Context c){synchronized(LOCK){try{SharedPreferences p=prefs(c);JSONArray rows=new JSONArray(p.getString("reminders","[]"));cancel(c,rows);if(!p.getBoolean("enabled",false))return;AlarmManager alarms=(AlarmManager)c.getSystemService(Context.ALARM_SERVICE);long now=System.currentTimeMillis();for(int n=0;n<rows.length();n++){JSONObject r=rows.getJSONObject(n);String id=r.getString("id");long end=r.getLong("end");if(p.getBoolean("sent:"+id+":"+end,false))continue;if(end<=now){if(end>0&&now-end<7L*86400000)c.sendBroadcast(new Intent(c,ReminderReceiver.class).setAction("fr.atelierdugoblin.REMINDER").putExtra("id",id).putExtra("end",end));continue;}if(KitchenTimerBridge.exact(c))alarms.setExactAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,end,pending(c,id,end));else alarms.setAndAllowWhileIdle(AlarmManager.RTC_WAKEUP,end,pending(c,id,end));}}catch(Exception e){prefs(c).edit().putString("error","Android n’a pas enregistré tous les rappels. Vérifie ses autorisations.").commit();}}}
    static void queue(Context c,String id,long end,String action)throws Exception{synchronized(LOCK){SharedPreferences p=prefs(c);JSONArray rows=new JSONArray(p.getString("reminders","[]")),actions=new JSONArray(p.getString("actions","[]"));if(actions.length()>=500)throw new IllegalStateException();JSONObject selected=null;for(int n=0;n<rows.length();n++){JSONObject r=rows.getJSONObject(n);if(r.getString("id").equals(id)&&r.getLong("end")==end)selected=r;}if(selected==null||p.getBoolean("actioned:"+id+":"+end,false))return;
        JSONObject a=new JSONObject().put("operation_id","reminder-"+UUID.randomUUID()).put("base",p.getString("base","")).put("identity",p.getString("identity","")).put("reminder_id",Long.parseLong(id)).put("due_key",selected.getString("due_key")).put("expected_epoch_ms",end).put("action",action);
        if(action.matches("10|30|60")){long next=((System.currentTimeMillis()+Long.parseLong(action)*60000)/1000)*1000;a.put("snooze_epoch_ms",next);selected.put("end",next);}else selected.put("end",0);
        if(!id.equals("0"))actions.put(a);if(!p.edit().putString("actions",actions.toString()).putString("reminders",rows.toString()).putBoolean("actioned:"+id+":"+end,true).commit())throw new IllegalStateException();((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).cancel("reminder:"+id,0);resume(c);
    }}
}
